import XCTest
@testable import iPhone

/// Surah lengths in quarters and thirds of a page (`SurahPageLength`, generated by
/// Scripts/build_surah_page_lengths.py from the 15-line layout).
final class SurahPageLengthTests: XCTestCase {
    private let lengths = (1...114).compactMap { SurahPageLength.twelfths(surahID: $0) }

    func testEverySurahHasALength() {
        XCTAssertEqual(lengths.count, 114)
        XCTAssertNil(SurahPageLength.twelfths(surahID: 0))
        XCTAssertNil(SurahPageLength.twelfths(surahID: 115))
    }

    func testLengthsAddUpToTheWholeMushaf() {
        XCTAssertEqual(lengths.reduce(0, +), 604 * 12, "the 114 lengths must sum to 604 pages")
    }

    func testLengthsSitOnTheQuarterAndThirdGrid() {
        for (index, twelfths) in lengths.enumerated() {
            XCTAssertGreaterThanOrEqual(twelfths, 3, "surah \(index + 1) is shorter than a quarter page")
            XCTAssertTrue([0, 3, 4, 6, 8, 9].contains(twelfths % 12), "surah \(index + 1): \(twelfths)/12")
        }
    }

    func testKnownLengths() {
        XCTAssertEqual(SurahPageLength.twelfths(surahID: 1), 12, "al-Fatihah fills page 1")
        XCTAssertEqual(SurahPageLength.twelfths(surahID: 2), 48 * 12, "al-Baqarah fills pages 2 to 49")
        XCTAssertEqual(SurahPageLength.twelfths(surahID: 67), 28, "al-Mulk: 35 of 15-line pages = 2 1/3")
    }

    func testLabels() {
        XCTAssertEqual(SurahPageLength.label(twelfths: 3), "¼ Page")
        XCTAssertEqual(SurahPageLength.label(twelfths: 9), "¾ Page")
        XCTAssertEqual(SurahPageLength.label(twelfths: 12), "1 Page")
        XCTAssertEqual(SurahPageLength.label(twelfths: 18), "1½ Pages")
        XCTAssertEqual(SurahPageLength.label(twelfths: 28), "2⅓ Pages")
        XCTAssertEqual(SurahPageLength.label(twelfths: 32), "2⅔ Pages")
        XCTAssertEqual(SurahPageLength.label(twelfths: 576), "48 Pages")
        XCTAssertEqual(SurahPageLength.label(twelfths: 9, short: true), "¾ Pg")
        XCTAssertEqual(SurahPageLength.label(twelfths: 28, short: true), "2⅓ Pgs")
    }
}
